export const freshProgress=()=>({version:3,introSeen:false,tutorialDone:false,unlocked:0,stars:[0,0,0,0,0],correct:0,attempts:0,hero:0,difficulty:'easy',subject:'all',pace:0,sound:false});
export function validProgress(x){if(!x||x.version!==3||!Number.isInteger(x.unlocked)||x.unlocked<0||x.unlocked>4||!Array.isArray(x.stars)||x.stars.length!==5||!x.stars.every(n=>Number.isInteger(n)&&n>=0&&n<=3)||!Number.isInteger(x.hero)||x.hero<0||x.hero>2||!Object.hasOwn(difficultyLabels,x.difficulty)||!['all','math','vietnamese','science','english'].includes(x.subject)||![0,15].includes(x.pace)||typeof x.introSeen!=='boolean'||typeof x.tutorialDone!=='boolean'||typeof x.sound!=='boolean'||!Number.isSafeInteger(x.correct)||!Number.isSafeInteger(x.attempts)||x.correct<0||x.attempts<x.correct)throw Error('Invalid progress');return x;}
export const damageByDifficulty={easy:100,normal:125,hard:150};
export function hitDamage(b,d){return Math.round((b.atk??100)*damageByDifficulty[d]/100);}
export function npcDamage(b){return (b.guard?1:2)+(b.tier===2?1:0);}
export const newBattle=(map,tier=0,{atk=100,hp=12}={})=>({map,tier,atk,maxShield:hp,wave:0,hp:300+tier*100,maxHp:300+tier*100,shield:hp,mistakes:0,correct:0,turn:0,status:'active',guard:false});
export function settle(b,correct,difficulty='easy'){if(b.status!=='active')return b;if(!Object.hasOwn(damageByDifficulty,difficulty))throw Error('Invalid difficulty');const n={...b,guard:correct,status:'npc'};if(correct){n.hp=Math.max(0,n.hp-hitDamage(b,difficulty));n.correct++;if(n.hp===0){if(!n.wave){n.wave=1;n.hp=400+(b.tier||0)*150;n.maxHp=n.hp;n.status='wave';}else n.status='won';}}else n.mistakes++;return n;}
export function npcTurn(b){if(b.status!=='npc')return b;const n={...b,shield:Math.max(0,b.shield-npcDamage(b)),turn:b.turn+1,status:'active'};if(n.shield===0)n.status='lost';return n;}
export function award(p,b){if(b.status!=='won')return p;const n=structuredClone(p);n.stars[b.map]=Math.max(n.stars[b.map],Math.max(1,3-b.mistakes));n.unlocked=Math.max(n.unlocked,Math.min(4,b.map+1));return n;}
export function makeDeck(bank,subject,difficulty,rng=Math.random){const deck=bank.filter(q=>(subject==='all'||q.subject===subject)&&q.difficulty===difficulty).slice();for(let i=deck.length-1;i>0;i--){const j=Math.floor(rng()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}return deck;}
